import { escapeText } from './html.js'
import { renderInline } from './inline.js'
import { DEFINITION_LINE, normalizeLabel } from './defs.js'

const FENCE = /^(`{3,})([^`]*)$/
const HEADING = /^(#{1,6}) (.*)$/
const ITEM = /^( *)- (.*)$/

/** One refusal of a document line, carrying the 1-based line it was read at. */
export class BlockError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'BlockError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Add one bullet item, at its capped level, to an in-progress list.
 * @param {{items: object[], stack: object[][]}} list - the list under construction.
 * @param {string} text - the item's own text.
 * @param {number} rawLevel - the level the leading spaces suggest, before capping.
 */
function addItem(list, text, rawLevel) {
  const stack = list.stack
  const level = Math.min(rawLevel, stack.length)
  let target
  if (level === stack.length) {
    if (stack.length === 0) {
      target = list.items
    } else {
      const parentArray = stack[stack.length - 1]
      const parentItem = parentArray[parentArray.length - 1]
      parentItem.children = []
      target = parentItem.children
    }
    stack.push(target)
  } else {
    stack.length = level + 1
    target = stack[stack.length - 1]
  }
  target.push({ text })
}

/**
 * The blocks of one document.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, {url: string, source: string}>} [defs] - definitions already in force
 *   (from a definitions file), extended with any the document itself defines.
 * @returns {{kind: string, level?: number, text?: string, lines?: string[], items?: object[], info?: string, content?: string[]}[]} the blocks in document order.
 * @throws {BlockError} on an unterminated fence or a label defined twice.
 */
export function parse(lines, defs = new Map()) {
  const out = []
  let paragraph = []
  let list
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (list !== undefined) {
      out.push({ kind: 'list', items: list.items })
      list = undefined
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
