const match = DEFINITION_LINE.exec(trimmed)
const label = match === null ? '' : normalizeLabel(match[1])
if (match === null || label === '') throw new DefsError(line, 'expected [label]: <url>')
const url = match[2].trim()
if (defs.has(label)) throw new DefsError(line, `label ${label} is defined twice`)
defs.set(label, { url, source: 'file' })
